from pathlib import Path
import json,hashlib,time,importlib.metadata as md
import numpy as np
from PIL import Image,ImageDraw
import torch
from transformers import AutoImageProcessor,AutoModelForDepthEstimation
p=Path(__file__).resolve().parents[2]/'depth-validation-20261102'; source=Path(__file__).resolve().parents[1]/'sources/BV1gttHeGE9Z_53.951826_4k.png';out=Path(__file__).resolve().parents[1]/'qa/depth-first-source';out.mkdir(exist_ok=True)
sha=lambda x:hashlib.sha256(x.read_bytes()).hexdigest()
assert sha(source)=='63a2fd0745a2a7623553ae53fe071511b42441b5a3e92b9c520c496436f00c11'
img=Image.open(source).convert('RGB');torch.set_num_threads(4);torch.set_num_interop_threads(1)
proc=AutoImageProcessor.from_pretrained(p/'model',local_files_only=True,trust_remote_code=False,use_fast=False)
model=AutoModelForDepthEstimation.from_pretrained(p/'model',local_files_only=True,trust_remote_code=False,use_safetensors=True).eval()
x=proc(images=img,return_tensors='pt');t=time.time()
with torch.inference_mode(): raw=model(**x).predicted_depth[0].cpu().numpy().astype('float32')
np.save(out/'relative-inverse-depth-model-grid.npy',raw,allow_pickle=False)
finite=np.isfinite(raw);lo=float(raw[finite].min());hi=float(raw[finite].max());gray=np.where(finite,np.clip((raw-lo)/(hi-lo),0,1)*65535,0).round().astype('uint16');Image.fromarray(gray).save(out/'relative-inverse-depth-gray16-model-grid.png')
# Display alignment only; never assert full-resolution independent predictions.
res=torch.nn.functional.interpolate(torch.from_numpy(raw)[None,None],size=(img.height,img.width),mode='bicubic',align_corners=False)[0,0].numpy()
Image.fromarray((np.clip((res-lo)/(hi-lo),0,1)*255).round().astype('uint8')).save(out/'relative-inverse-depth-gray8-resampled-source-grid.png')
# Conservative, manually inspected exclusion ROIs, not instance segmentation or confidence.
mask=Image.new('L',img.size);d=ImageDraw.Draw(mask);d.rectangle((500,1190,3510,1970),fill=4);d.rectangle((1940,1150,2070,1420),fill=1);d.rectangle((1370,0,1820,110),fill=2);mask.save(out/'manual-exclusion-classes-source-grid.png')
Image.new('L',img.size,255).save(out/'confidence-unknown-source-grid.png')
report={'purpose':'Newly reacquired ring-stage source relative-depth analysis, not recovered original F07 or reconstruction acceptance','source':{'path':str(source),'BV':'BV1gttHeGE9Z','part':1,'time_seconds':53.951826,'size':img.size,'bytes':source.stat().st_size,'sha256':sha(source),'crop':[0,0,img.width,img.height],'provenance':'Current source owner manifest: native paused ready4 before/after same time, actual4K; existing login UI; inspected by build owner'},'method':{'repo':'depth-anything/Depth-Anything-V2-Small-hf','revision':json.loads((p/'model-api.json').read_text())['sha'],'license':'apache-2.0','weights_sha256':sha(p/'model/model.safetensors'),'versions':{x:md.version(x) for x in ['torch','transformers','safetensors','pillow','numpy']},'device':'cpu','threads':4,'dtype':'float32','input_tensor_shape':list(x['pixel_values'].shape),'processor_config':json.loads((p/'model/preprocessor_config.json').read_text()),'raw_shape':list(raw.shape),'inference_and_output_seconds':time.time()-t,'trust_remote_code':False,'weights_format':'safetensors','local_files_only':True},'value_definition':'Model relative inverse-depth-like prediction: larger generally nearer, not metric distance, no absolute scale/calibration. Gray white=larger/nearer; black=smaller/farther. Orientation is model convention, not image luminance.','range':{'min':lo,'max':hi,'nonfinite_count':int((~finite).sum())},'normalization':'(raw-min)/(max-min); source-grid derived by bicubic align_corners=False; display clamp to [0,1]. Per-image normalization not cross-image distance.','mask':{'manual-exclusion-classes-source-grid.png':{'0':'unlabelled, NOT certified valid','1':'conservative character bounding rectangle includes nearby background','2':'upper event title uncertain graphic/text region, conservative exclusion','3':'not assigned; no certified sky segmentation','4':'conservative stage disc/reflections/projected fish and lighting region, overlaps valid platform; not exact segmentation'},'confidence-unknown-source-grid.png':'255 everywhere means model supplies NO calibrated confidence, not high confidence','reflection_water_transparency_lights':'Dynamic pink/orange beams cross geometry throughout frame, unsegmented and untrusted. Moving fish/sparks/reflections on stage in conservative mask4; character mask1 excludes dynamic person; all nonzero categories excluded. Star-chain identity/state unknown; no confident static correspondence. Mask coverage incomplete; 0 is not valid certificate.','occluded_hidden_geometry':'not measurable from this monocular image; no fabricated completion'},'limitations':['Stylized ring stage, glowing lights and moving overlays are domain-shifted','No metric truth, hidden geometry, contacts or unique cameras established','A visually plausible map does not validate object geometry','No current source reconstruction or new scene delivered by this test']}
report['outputs']=[{'path':f.name,'bytes':f.stat().st_size,'sha256':sha(f),'size':list(Image.open(f).size) if f.suffix=='.png' else None} for f in sorted(out.iterdir()) if f.is_file()]
(out/'report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));print(json.dumps({k:report[k] for k in ['method','range']},indent=2))
